<div class="sl-head"><div><h1 class="sl-title">Delivery to your door</h1><p class="sl-lede">Choose a ready parcel, confirm your location and approve the price before dispatch.</p></div><a class="sl-btn ghost" href="<?= h(sl_route('PickupCodes')) ?>">Pickup codes</a></div>
<?php if(!$d['ready']): ?><div class="sl-card sl-empty">Delivery requests are not available yet. Please contact the office.</div><?php return;endif; ?>
