<?php if($r->state==='quoted'): ?>
<div class="sl-card col g12"><h2 class="sl-ct">Confirm your delivery price</h2><p>This quote expires at <?= h(sl_date($r->expires_at,'M j, H:i')) ?>. The delivery fee is separate from your shipping bill and is due on delivery. Accounts clearance is required before dispatch.</p>
<form data-sl-form data-sl-redirect method="post" action="ajax/sl/delivery_ajax.php"><input type="hidden" name="op" value="approve"><input type="hidden" name="id" value="<?= (int)$r->id ?>"><button class="sl-btn block" type="submit">Approve <?= h(dl_money((int)$r->amount_cents,$r->currency)) ?> and request delivery</button></form><a href="delivery_request.php" class="sl-btn ghost">Change location or parcels</a></div>
<?php elseif(in_array($r->state,['pending','assigned','failed'],true)): ?>
<button class="sl-btn ghost" data-sl-action="ajax/sl/delivery_ajax.php" data-p-op="cancel" data-p-id="<?= (int)$r->id ?>" data-sl-confirm="Cancel this delivery request?" data-sl-reload>Cancel delivery request</button>
<?php endif; ?>
<?php else: ?>
<?php if(!$d['config']['enabled']): ?><div class="sl-banner info">Delivery requests are currently paused. Please contact support for assistance.</div>
<?php elseif(!$d['parcels']): ?><section class="sl-card sl-empty"><h2 class="sl-ct">No parcels ready for a delivery request</h2><p>A parcel appears here when it reaches a ready status and has no active delivery.</p><a class="sl-btn" href="<?= h(sl_route('PublicTracking')) ?>">Track a parcel</a></section>
<?php else: ?>
<form id="dl-quote" class="split" data-sl-form data-sl-redirect method="post" action="ajax/sl/delivery_ajax.php"><input type="hidden" name="op" value="quote"><input type="hidden" name="place_id" id="dl-place"><input type="hidden" name="mode" value="<?= h($d['config']['default_mode']) ?>">
<section class="a sl-card col g16"><h2 class="sl-ct">1. Select your parcels</h2><label class="sl-field"><span class="sl-lab">Shipment type</span><select name="module" id="dl-module" class="sl-in"><?php foreach($d['parcels'] as $module=>$parcels): ?><option value="<?= h($module) ?>"><?= $module==='air'?'Air shipments':'Sea packages' ?></option><?php endforeach; ?></select></label>
<?php foreach($d['parcels'] as $module=>$parcels): ?><div class="col g8" data-dl-module="<?= h($module) ?>"><?php foreach($parcels as $p): ?><label class="dl-parcel"><input type="checkbox" name="parcels[]" value="<?= (int)$p->order_id ?>"><span class="grow"><b class="mono"><?= h($p->order_prefix.$p->order_no) ?></b><small class="mut"><?= h(str_replace('_',' ',$p->status_name)) ?></small></span></label><?php endforeach; ?></div><?php endforeach; ?>
<p class="mut sm">Select parcels of one shipment type and agency for each delivery.</p>
<h2 class="sl-ct">2. Your delivery contact</h2><label class="sl-field"><span class="sl-lab">Contact name</span><input class="sl-in" name="contact_name" maxlength="150" required autocomplete="name" value="<?= h(trim(($userData->fname??'').' '.($userData->lname??''))) ?>"></label><label class="sl-field"><span class="sl-lab">Phone number</span><input class="sl-in" type="tel" name="contact_phone" required maxlength="30" autocomplete="tel" value="<?= h($userData->phone??'') ?>"></label><label class="sl-field"><span class="sl-lab">Landmark, entrance or delivery instructions</span><textarea class="sl-in" name="instructions" maxlength="500" rows="3" placeholder="E.g. blue gate opposite the pharmacy"></textarea></label>
</section><section class="b sl-card col g16"><h2 class="sl-ct">3. Confirm your Google Maps location</h2><p class="mut">Search for your building or a nearby landmark. Check the pin and add entrance instructions.</p><div id="dl-place-search"></div><button type="button" class="sl-btn ghost" id="dl-locate">Use my current location</button><div id="dl-map" class="dl-map" role="region" aria-label="Delivery location map"></div><p id="dl-location" role="status">Select a Google Maps result to get a price.</p><div id="dl-map-error" class="sl-banner warn" hidden>Google Maps could not load. Please retry or contact support.</div><p class="mut sm">Pricing: <?= h($d['config']['default_mode']) ?> · <?= h($d['config']['currency']) ?>. Road distance and the final price are calculated by the server.</p><button type="submit" class="sl-btn block" id="dl-quote-button" disabled>Get delivery price</button></section></form>
<div id="dl-map-config" data-browser-key="<?= h(getenv('CDP_GOOGLE_MAPS_BROWSER_KEY')?:$d['config']['browser_key']) ?>" data-country="<?= h($d['config']['country']) ?>" data-origin="<?= h($d['config']['origin_place_id']) ?>"></div>
<?php endif;endif; ?>
